// Random arcade game for the GitHub profile README.
// Each request picks one of six games at random and serves it with no-cache headers,
// so GitHub's image proxy fetches a fresh pick on every page load.
// The SVGs themselves are generated by .github/workflows/profile-art.yml into the `output` branch.

const BASE = "https://raw.githubusercontent.com/StefanMarinkov05/StefanMarinkov05/output/";
const GAMES = {
  pacman: "pacman-contribution-graph",
  galaga: "galaga-contribution-graph",
  breakout: "breakout-contribution-graph",
  "puzzle-bobble": "puzzle-bobble-contribution-graph",
  bomberman: "bomberman-contribution-graph",
  snake: "github-snake",
};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const dark = url.searchParams.get("theme") === "dark";
    const names = Object.keys(GAMES);
    const asked = url.searchParams.get("game");
    const game = names.includes(asked)
      ? asked
      : names[crypto.getRandomValues(new Uint32Array(1))[0] % names.length];
    const file = `${GAMES[game]}${dark ? "-dark" : ""}.svg`;

    // Upstream copy is cached at the edge for 10 minutes; the response to the viewer is never cached.
    const upstream = await fetch(BASE + file, { cf: { cacheTtl: 600, cacheEverything: true } });
    if (!upstream.ok) {
      return new Response(`upstream ${upstream.status}`, { status: 502 });
    }
    return new Response(upstream.body, {
      headers: {
        "content-type": "image/svg+xml; charset=utf-8",
        "cache-control": "no-cache, no-store, must-revalidate, max-age=0",
        expires: "0",
        "x-game": game,
      },
    });
  },
};
